<template>
  <q-btn
    flat
    color="white"
    icon="error_outline"
    class="helpbtn notification-history-btn"
  >
    <div
      v-if="errorHistory.length > 0"
      class="notification-badge"
    >
      {{ errorHistory.length }}
    </div>
    <q-tooltip>{{ $t('recent_errors') }}</q-tooltip>
    <q-menu
      class="notification-history-menu"
      anchor="bottom middle"
      self="top middle"
      :offset="[0, 8]"
    >
      <div class="notification-history-panel">
        <div class="notification-history-header">
          <span class="notification-history-title">{{ $t('recent_errors') }}</span>
          <q-btn
            v-if="errorHistory.length > 0"
            flat
            dense
            size="sm"
            class="notification-clear-btn"
            @click="clearHistory"
          >
            {{ $t('clear') }}
          </q-btn>
        </div>

        <div v-if="errorHistory.length === 0" class="notification-empty">
          <q-icon name="check_circle" size="32px" class="notification-empty-icon" />
          <span>{{ $t('no_recent_errors') }}</span>
        </div>

        <div v-else class="notification-list">
          <div
            v-for="entry in errorHistory"
            :key="entry.key"
            class="notification-entry"
          >
            <div class="notification-entry-header">
              <span class="notification-entry-message">
                {{ entry.message }}
                <span v-if="entry.count > 1" class="notification-entry-count">
                  × {{ entry.count > 99 ? '99+' : entry.count }}
                </span>
              </span>
              <q-btn
                v-if="entry.detail"
                flat
                dense
                size="xs"
                class="notification-copy-btn"
                @click.stop="copyError(entry)"
              >
                Copy
              </q-btn>
            </div>
            <div v-if="entry.detail" class="notification-entry-detail">
              {{ entry.detail }}
            </div>
            <div class="notification-entry-meta">
              <span class="notification-entry-route">{{ entry.route }}</span>
              <span class="notification-entry-time">{{ formatTime(entry.lastOccurredAt) }}</span>
            </div>
          </div>
        </div>
      </div>
    </q-menu>
  </q-btn>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { errorHistory, clearErrorHistory } from './notify';
import type { ErrorHistoryEntry } from './notify';

export default defineComponent({
  name: 'NotificationHistory',
  setup() {
    return { errorHistory };
  },
  methods: {
    formatTime(date: Date): string {
      return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' });
    },
    copyError(entry: ErrorHistoryEntry): void {
      const text = entry.detail
        ? `${entry.message}\n${entry.detail}\nRoute: ${entry.route}`
        : `${entry.message}\nRoute: ${entry.route}`;
      navigator.clipboard.writeText(text).catch(() => {});
    },
    clearHistory(): void {
      clearErrorHistory();
    },
  },
});
</script>

