<!--
  Multi-Org Switcher entry point (M2, SD 2860679170 §4.2).

  KONZEPT-FIX (DOCB-13399): originally built into the sidebar user menu
  (UserDropDown.vue) as an inline dropdown — the wrong location and the
  wrong interaction per the Product Owner's binding correction. This is now
  a standalone, always-top-right header icon, deliberately separate from
  the pre-existing SUB-ORG switcher (Sub-Header.vue's "sub-orgs-button" —
  parent org -> child sub-orgs, a different concept entirely and NOT to be
  touched or reused for this).

  Clicking navigates to the full-page org picker (/select-organisation,
  OrgPicker.vue) in its "switch" mode — the SAME UI the post-login M1 picker
  uses, per the PO's final spec (no inline dropdown). OrgPicker.vue itself
  performs the actual org-switch/token-exchange (reusing the logic that used
  to live in UserDropDown.vue#onSwitchOrg).
-->
<template>
  <q-btn
    v-if="myOrganisations.length > 1"
    id="header_multiorg_switch_button"
    flat
    class="helpbtn"
    color="white"
    icon="swap_horiz"
    data-test="header-multiorg-switch"
    @click="goToOrgSwitch"
  >
    <q-tooltip>{{ $t('org_switcher_header') }}</q-tooltip>
  </q-btn>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import type { MeOrganisationItem } from 'src/sdk/auth/models';

export default defineComponent({
  name: 'HeaderOrgSwitchButton',
  data() {
    return {
      // Hidden entirely for single-org users — nothing to switch to, same
      // guard the old UserDropDown.vue block used.
      myOrganisations: [] as MeOrganisationItem[],
    };
  },
  mounted() {
    this.loadMyOrganisations();
  },
  methods: {
    // Non-critical header decoration: failures are swallowed (logged)
    // rather than surfaced — a user with one org (or a failed fetch) simply
    // sees no switcher icon.
    async loadMyOrganisations() {
      try {
        const { userApiService } = await import('src/services');
        const response = await userApiService.getMyOrganisations();
        this.myOrganisations = response?.organisations ?? [];
      } catch (err) {
        logError(err);
        this.myOrganisations = [];
      }
    },
    goToOrgSwitch() {
      this.$router.push('/select-organisation?mode=switch');
    },
  },
});
</script>
