<template>
  <span v-if="shouldRender" class="region-flag" :title="tooltip" :aria-label="tooltip">
    <img :src="flagSrc" :alt="tooltip" />
  </span>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { isRegionalStage, onApiRegionChange, type ApiRegion } from 'src/pages/api-base-url';

const FLAG_SRC: Record<ApiRegion, string> = {
  eu: '/images/Flag_of_Europe.svg',
  us: '/images/Flag_of_the_United_States.svg',
};

const STAGE_SHOWS_FLAG = isRegionalStage();

export default defineComponent({
  name: 'RegionFlag',
  data() {
    return {
      region: null as ApiRegion | null,
    };
  },
  computed: {
    shouldRender(): boolean {
      return STAGE_SHOWS_FLAG && this.region !== null;
    },
    tooltip(): string {
      return this.region === 'us' ? 'US region' : 'EU region';
    },
    flagSrc(): string {
      return this.region ? FLAG_SRC[this.region] : '';
    },
  },
  mounted() {
    onApiRegionChange(this.handleRegionChange);
  },
  methods: {
    handleRegionChange(next: ApiRegion) {
      this.region = next;
    },
  },
});
</script>

<style scoped>
.region-flag {
  display: inline-flex;
  align-items: center;
  margin-left: 8px;
}
.region-flag img {
  display: block;
  height: 24px;
  max-width: 36px;
  width: auto;
  border-radius: var(--radius-sm);
}
</style>
