<template>
  <slot></slot>
</template>
<script lang="ts">
import { defineComponent, nextTick, PropType } from 'vue';
import type ShepherdBase from 'shepherd.js';
import type { Tour } from 'shepherd.js';
// Lazy-loaded: shepherd.js (119 KB) only fetched when walkthrough actually starts
let Shepherd: typeof ShepherdBase;
import { storeToRefs } from 'pinia';
import { useSettingStore } from 'src/store/main';
import { walkthrough_completed_setting } from 'src/constants';
import { getUserPreferences } from 'src/sdk/api/user-preferences/user-preferences';
import { getOrgId } from 'src/utils/organization/org_id_helper';

type PopperPlacement =
  | 'auto'
  | 'auto-start'
  | 'auto-end'
  | 'top'
  | 'top-start'
  | 'top-end'
  | 'bottom'
  | 'bottom-start'
  | 'bottom-end'
  | 'right'
  | 'right-start'
  | 'right-end'
  | 'left'
  | 'left-start'
  | 'left-end';

type WalkthroughStep = {
  id: string;
  text: string;
  attachTo?: {
    element: string;
    on?: PopperPlacement;
  };
  buttons?: Array<{ text: string; action: () => void }>;
  disableBack?: boolean;
  disableNext?: boolean;
  addFinish?: boolean;
  triggerClick?: string;
  triggerScroll?: string;
  classes?: string;
};

declare const logError: (...args: unknown[]) => void;

function normalizePreference(value: unknown): boolean | undefined {
  console.log('[normalizePreference] Input value:', value, 'Type:', typeof value);

  // Handle boolean directly
  if (typeof value === 'boolean') {
    console.log('[normalizePreference] ✅ Detected boolean:', value);
    return value;
  }

  // Handle string values
  if (typeof value === 'string') {
    const normalized = value.trim().toLowerCase();
    if (['true', '1', 'yes'].includes(normalized)) {
      console.log('[normalizePreference] ✅ Detected string true:', value);
      return true;
    }
    if (['false', '0', '', 'no', 'null'].includes(normalized)) {
      console.log('[normalizePreference] ✅ Detected string false:', value);
      return false;
    }
    console.log('[normalizePreference] ⚠️ Unknown string value:', value);
  }

  // Handle numeric values
  if (typeof value === 'number') {
    const result = value === 1;
    console.log('[normalizePreference] ✅ Detected number:', value, '→', result);
    return result;
  }

  // Handle null/undefined
  if (value === null || value === undefined) {
    console.log('[normalizePreference] ⚠️ Value is null/undefined');
    return undefined;
  }

  // Handle object responses (API wrapper formats)
  if (typeof value === 'object') {
    console.log('[normalizePreference] Checking object properties...');
    const candidate =
      (value as Record<string, unknown>).value ??
      (value as Record<string, unknown>).preference ??
      (value as Record<string, unknown>).data ??
      (value as Record<string, unknown>).result ??
      (value as Record<string, unknown>).val;

    if (candidate !== undefined) {
      console.log('[normalizePreference] Found nested value, recursing:', candidate);
      return normalizePreference(candidate);
    }

    // Last resort: check if object itself is truthy (non-empty object)
    const keys = Object.keys(value);
    if (keys.length === 0) {
      console.log('[normalizePreference] ⚠️ Empty object');
      return undefined;
    }

    console.log('[normalizePreference] ⚠️ Object with keys but no matching property:', keys);
  }

  console.log('[normalizePreference] ❌ Unable to normalize, returning undefined');
  return undefined;
}

export default defineComponent({
  name: 'WalkthroughGuide',
  props: {
    steps: {
      type: Array as PropType<WalkthroughStep[]>,
      required: true,
    },
  },
  data() {
    return {
      tour: null as Tour | null,
      hasInteracted: false,
      doNotShowAgainChecked: false,
    };
  },
  setup() {
    const settingsStore = useSettingStore();
    const { updateSetting } = settingsStore;
    const { user_settings } = storeToRefs(settingsStore);

    return {
      user_settings,
      updateSetting,
      settings_store: settingsStore,
    };
  },
  async mounted() {
    // Wait briefly for org_id to be available (set during auth)
    // This helps avoid the race condition where org_id isn't set yet
    let retries = 0;
    while (!getOrgId() && retries < 10) {
      await new Promise((resolve) => setTimeout(resolve, 100));
      retries++;
    }

    if (!getOrgId()) {
      console.warn('[WalkthroughGuide] ⚠️ org_id still not available after retries');
    }

    const shouldShow = await this.checkWalkthroughPreference();
    if (shouldShow) {
      await nextTick();
      this.initTour();
      this.startTour();
    }

    const orgColor = this.user_settings?.ORG_COLOR_PREFERENCE as
      | string
      | undefined;
    if (orgColor) {
      document.documentElement.style.setProperty('--org-color', orgColor);
    }
  },
  methods: {
    async checkWalkthroughPreference() {
      try {
        const orgId = getOrgId();

        if (!orgId) {
          return true;
        }

        // Get all user preferences via SDK
        const apiModule = getUserPreferences();
        const response = await apiModule.getUserPreferencesPreferencesGetUserPreferencesGet({
          org_id: orgId,
        });

        // Extract the specific preference from the list
        const preferencesData = (response as any)?.data || response;
        const walkthrough = (preferencesData as Record<string, any>)?.[walkthrough_completed_setting];
        const preference = normalizePreference(walkthrough);
        const shouldShow = preference !== true;
        return shouldShow;
      } catch (error) {
        // If preference check fails, show walkthrough as default
        return true;
      }
    },
    async initTour() {
      if (!this.steps.length) {
        return;
      }

      if (this.tour && typeof this.tour.cancel === 'function') {
        this.tour.cancel();
      }

      this.hasInteracted = false;
      this.doNotShowAgainChecked = false; // Reset checkbox state for new tour

      // Lazy-load shepherd.js on first use
      if (!Shepherd) {
        const mod = await import('shepherd.js');
        Shepherd = mod.default;
      }

      this.tour = new Shepherd.Tour({
        useModalOverlay: true,
        defaultStepOptions: {
          cancelIcon: { enabled: true },
          classes: 'shadow-md bg-primary text-white',
          scrollTo: { behavior: 'smooth', block: 'center' },
        },
      });

      const tourInstance = this.tour;

      tourInstance.on('complete', () => {
        // Always save on complete (tour finished)
        this.saveWalkthroughCompleted();
      });

      tourInstance.on('cancel', () => {
        // Check if "Don't show again" was checked before tour closes
        // Only save if checkbox was checked, not automatically on cancel
        this.checkAndSaveDoNotShowAgain();
      });

      tourInstance.on('show', (event: any) => {
        if (event?.step?.id === this.steps[0]?.id) {
          // CRITICAL FIX: Wait for Shepherd to render the DOM before attaching event listeners
          // Without this delay, document.getElementById returns null and event listener is never attached
          nextTick(() => {
            // Add extra safety delay to ensure Shepherd's DOM rendering is complete
            setTimeout(() => {
              this.addDoNotShowAgainCheckbox();
            }, 50);
          });
        }
      });

      const filteredSteps = this.steps.filter((step) => {
        const selector = step.attachTo?.element || 'body';
        const element = selector ? document.querySelector(selector) : null;
        return Boolean(element) || selector === '.dashboard';
      });

      filteredSteps.forEach((step, index) => {
        const currentTour = this.tour;
        if (!currentTour) {
          return;
        }

        let stepText = step.text;
        if (index === 0) {
          stepText += `<br><br><label><input type="checkbox" id="do-not-show-again-checkbox"> ${this.$t('dont_show_again')}</label>`;
        }

        currentTour.addStep({
          id: step.id,
          text: stepText,
          attachTo: step.attachTo || { element: 'body', on: 'top' },
          buttons: step.buttons || [
            ...(step.disableBack
              ? []
              : [
                  {
                    text: this.$t('guide_back') as string,
                    action: () => currentTour.back(),
                  },
                ]),
            ...(step.disableNext
              ? []
              : [
                  {
                    text: this.$t('guide_next') as string,
                    action: () => currentTour.next(),
                  },
                ]),
            ...(step.addFinish
              ? [
                  {
                    text: this.$t('guide_finish') as string,
                    action: () => currentTour.complete(),
                  },
                ]
              : []),
          ],
          classes: step.classes,
          modalOverlayOpeningRadius: 7,
          beforeShowPromise: () =>
            Promise.race([
              new Promise<void>((resolve) => {
                if (step.triggerClick) {
                  const button = document.querySelector(step.triggerClick);
                  if (button instanceof HTMLElement) {
                    setTimeout(() => {
                      button.click();
                      resolve();
                    }, 100);
                    return;
                  }
                  // FIX: Always resolve even if button not found
                  resolve();
                  return;
                }

                if (step.triggerScroll) {
                  const target = document.querySelector(step.triggerScroll);
                  if (target) {
                    target.scrollIntoView({
                      behavior: 'auto',
                      inline: 'center',
                      block: 'nearest',
                    });
                    setTimeout(() => resolve(), 200);
                    return;
                  }
                  // FIX: Always resolve even if target not found
                  resolve();
                  return;
                }

                resolve();
              }),
              // Safety timeout: resolve after 5 seconds to prevent infinite hangs
              new Promise<void>((resolve) => setTimeout(resolve, 5000)),
            ]),
        });
      });
    },
    startTour() {
      if (this.tour && typeof this.tour.isActive === 'function') {
        if (this.tour.isActive()) {
          this.tour.cancel();
        }
        this.tour.start();
      }
    },
    async saveWalkthroughCompleted() {
      try {
        console.log(
          '[WalkthroughGuide] saveWalkthroughCompleted() called - saving preference...',
        );
        // Use setUserPreferences() to save as USER preference (not org preference)
        // This ensures the preference persists across logout/login
        const result = await this.settings_store.setUserPreferences(
          walkthrough_completed_setting,
          true,
        );
        console.log(
          '[WalkthroughGuide] Preference saved via setUserPreferences(), result:',
          result,
        );

        // Verify it was saved by immediately reading it back via SDK
        const orgId = getOrgId();
        if (orgId) {
          const apiModule = getUserPreferences();
          const verification = await apiModule.getUserPreferencesPreferencesGetUserPreferencesGet({
            org_id: orgId,
          });
          const preferencesData = (verification as any)?.data || verification;
          const savedValue = (preferencesData as Record<string, any>)?.[walkthrough_completed_setting];
          console.log('[WalkthroughGuide] ✅ Verification read-back:', savedValue);
        }
      } catch (error) {
        console.error(
          '[WalkthroughGuide] FAILED to save walkthrough completion:',
          error,
        );
        logError?.('Failed to save walkthrough completion state:', error);
      }
    },
    async checkAndSaveDoNotShowAgain() {
      // Use stored state instead of trying to read from DOM
      // (DOM may already be destroyed when cancel event fires)

      if (!this.doNotShowAgainChecked) {
        console.log(
          '[WalkthroughGuide] Checkbox was not checked - walkthrough will show on next login',
        );
        return;
      }

      try {
        console.log(
          '[WalkthroughGuide] Checkbox was checked - ensuring preference is saved...',
        );
        const result = await this.settings_store.setUserPreferences(
          walkthrough_completed_setting,
          true,
        );
        console.log('[WalkthroughGuide] Final save result:', result);

        // Verify it was saved via SDK
        const orgId = getOrgId();
        if (orgId) {
          const apiModule = getUserPreferences();
          const verification = await apiModule.getUserPreferencesPreferencesGetUserPreferencesGet({
            org_id: orgId,
          });
          const preferencesData = (verification as any)?.data || verification;
          const savedValue = (preferencesData as Record<string, any>)?.[walkthrough_completed_setting];
          console.log('[WalkthroughGuide] Verification:', savedValue);
        }
        console.log('[WalkthroughGuide] ✅ Walkthrough will not show again');
      } catch (error) {
        console.error('[WalkthroughGuide] FAILED to save preference:', error);
      }
    },
    addDoNotShowAgainCheckbox() {
      const checkbox = document.getElementById('do-not-show-again-checkbox');
      if (!checkbox) {
        console.error(
          '[WalkthroughGuide] CRITICAL: Checkbox element not found in DOM! Event listener will NOT be attached.',
        );
        console.error(
          '[WalkthroughGuide] This means checkbox clicks will not be detected.',
        );
        return;
      }

      console.log(
        '[WalkthroughGuide] ✅ Checkbox element found - attaching event listener',
      );
      checkbox.removeEventListener(
        'change',
        this.handleDoNotShowAgainChange as EventListener,
      );
      checkbox.addEventListener(
        'change',
        this.handleDoNotShowAgainChange as EventListener,
      );
      console.log('[WalkthroughGuide] ✅ Event listener attached successfully');
    },
    async handleDoNotShowAgainChange(event: Event) {
      const target = event.target as HTMLInputElement | null;
      if (!target) {
        return;
      }

      // Store checkbox state immediately in component data
      this.doNotShowAgainChecked = target.checked;
      console.log(
        '[WalkthroughGuide] Checkbox state changed:',
        this.doNotShowAgainChecked,
      );

      // Save immediately when checkbox is checked
      if (target.checked) {
        try {
          console.log(
            '[WalkthroughGuide] Checkbox checked - saving preference immediately...',
          );
          await this.settings_store.setUserPreferences(
            walkthrough_completed_setting,
            true,
          );
          console.log('[WalkthroughGuide] Preference saved successfully');
        } catch (error) {
          console.error(
            'Failed to save "do not show again" preference:',
            error,
          );
        }
      }
    },
  },
  watch: {
    steps: {
      handler() {
        // Only init tour, don't auto-start it
        // This allows the watch to update translations without restarting the tour
        if (!this.steps.length) {
          return;
        }

        // Don't reinitialize if tour is already active
        if (this.tour && this.tour.isActive()) {
          console.log(
            '[WalkthroughGuide] Tour already active - skipping reinit',
          );
          return;
        }

        this.initTour();
        // DON'T call startTour() here - only mounted() should start the tour
      },
      deep: true,
      immediate: false, // Changed from true to false
    },
  },
});
</script>
