<!--vbase-->
<template>
  <div
    v-if="message !== ''"
    class="q-dialog fullscreen q-dialog--modal banner-parent"
  >
    <div
      class="q-dialog__backdrop fixed-full"
      aria-hidden="true"
      style="--q-transition-duration: 300ms"
    ></div>
    <div class="alert-banner row q-dialog__inner all-pointer-events">
      <span class="message left-side">
        {{ message }}
      </span>

      <span class="close">
        <q-btn
          class="schedule-meeting text-weight-bold"
          unelevated
          @click="openCalendly"
        >
          {{ $t('schedule_meeting_alert') }}
        </q-btn>
        <q-btn dense flat icon="close" @click="closeAlert">
          <q-tooltip>{{ $t('close') }}</q-tooltip>
        </q-btn>
      </span>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { useSubscriptionStore, useUserStore } from 'src/store/main';
import cache from 'src/utils/cache';
import { contactUsWithCalendly } from 'src/utils/UserDetails';

export default defineComponent({
  el: '#app',
  mixins: [cache],
  props: {},
  components: {},
  data() {
    return {};
  },
  watch: {
    subscription_remaining_days: {
      handler: function (newVal, oldVal) {
        this.handleAlert();
      },
    },
    ready_to_expire_subscriptions: {
      handler: function (newVal, oldVal) {
        this.handleAlert();
      },
    },
  },
  mounted: async function () {
    // Ensure user_id is available before attempting to fetch subscription data
    const user_store = useUserStore();
    const user_id = user_store.getUserDetailByKey('id');

    // If user_id is not available, wait for profile to load
    if (!user_id || user_id === '') {
      console.log(
        '[SubscriptionAlert] user_id not available, fetching profile first...',
      );
      try {
        await user_store.getProfile();
        console.log('[SubscriptionAlert] Profile loaded successfully');
      } catch (error) {
        console.error('[SubscriptionAlert] Failed to load profile:', error);
        // Don't proceed if we can't get user_id
        return;
      }
    }

    // Wrap in try-catch to prevent subscription errors from breaking page load
    try {
      this.handleAlert();
    } catch (error) {
      console.error(
        '[SubscriptionAlert] Error during handleAlert, continuing without subscription data:',
        error,
      );
      // Silently fail - subscription data is non-critical
    }
  },
  methods: {
    closeAlert() {
      const subscription_store = useSubscriptionStore();
      subscription_store.subscriptionWindowClosed = true;
      this.message = '';
    },
    async handleAlert() {
      if (this.processing_request) {
        return;
      }
      this.processing_request = true;
      const subscription_store = useSubscriptionStore();
      const subscriptions_set_success =
        await subscription_store.setSubscriptionInfo();
      this.message = '';
      let messages = [];

      if (!subscription_store.subscriptionWindowClosed) {
        for (const subscription of this.ready_to_expire_subscriptions) {
          const sub_message = this.prepareMessageForAlert(
            subscription.days,
            subscription.detail.name,
          );
          if (sub_message != '') {
            messages.push(sub_message);
          }
        }
        if (messages.length == 0) {
          return;
        }

        this.message = messages.join(', ');
        this.processing_request = false;
      }
    },

    prepareMessageForAlert(days: number, name: string) {
      if (days == 0) {
        return this.$t('subscription_end_today');
      }

      if (days == -1) {
        return name + ' ' + this.$t('subscription_not_found');
      }

      if (days < 0) {
        return name + ' ' + this.$t('subscription_ended');
      }

      if (days == 1) {
        return (
          name + ' ' + this.$t('subscription_end_days') + days + this.$t('day')
        );
      }

      if (days > 0 && days < this.whenToShowAlertDays) {
        return (
          name + ' ' + this.$t('subscription_end_days') + days + this.$t('days')
        );
      }

      return '';
    },
    openCalendly() {
      contactUsWithCalendly();
    },
  },
  setup() {
    const subscription_store = useSubscriptionStore();
    const { ready_to_expire_subscriptions, whenToShowAlertDays } =
      storeToRefs(subscription_store);
    return {
      ready_to_expire_subscriptions: ready_to_expire_subscriptions,
      whenToShowAlertDays,
      message: ref(''),
      processing_request: ref(false),
    };
  },
});
</script>

