<template>
  <q-breadcrumbs separator="/" class="breadcrumb-nav">
    <q-breadcrumbs-el
      v-for="(crumb, index) in breadcrumbs"
      :key="index"
      :to="index === breadcrumbs.length - 1 ? undefined : crumb.to"
      :exact="true"
      class="breadcrumb-element"
      :class="{ 'breadcrumb-current': index === breadcrumbs.length - 1 }"
      active-class="font-weight-500"
    >
      <span class="breadcrumb-label">{{ crumb.label }}</span>
    </q-breadcrumbs-el>
  </q-breadcrumbs>
</template>

<script>
import { getOrgId } from 'src/utils/organization/org_id_helper';
import { useRoute } from 'vue-router';
import { nextTick } from 'vue';

export default {
  name: 'Breadcrumb',
  data() {
    return {
      breadcrumbs: [],
    };
  },
  setup() {
    // Try to get route, but handle case where router isn't available yet
    let route;
    try {
      route = useRoute();
    } catch (e) {
      // Router not available yet - component will handle gracefully
      console.debug(
        '[Breadcrumb] Router not available during setup, will retry on mount',
      );
      route = null;
    }
    return {
      route,
    };
  },
  watch: {
    $route() {
      this.generateBreadcrumbs();
    },
  },
  async mounted() {
    // Wait for Vue to complete rendering before accessing route
    await nextTick();
    this.generateBreadcrumbs();
  },
  methods: {
    formatLabel(label) {
      // return label.replace(/_/g, ' ').toLowerCase();
      if (label.includes(getOrgId())) {
         
        return label.replace(getOrgId(), '').replace(/_/g, ' ').toLowerCase();
      }
       
      return label;
    },
    generateBreadcrumbs() {
      // ✅ FIX: Add comprehensive null-checks for route before destructuring
      // This prevents "Cannot destructure property 'params' of 'this.route' as it is undefined" error
      if (!this.route || !this.route.params) {
        console.debug('[Breadcrumb] Route or route.params not available yet');
        return;
      }

      // Additional safety: Check meta exists and is an object
      if (!this.route.meta || typeof this.route.meta !== 'object') {
        console.debug('[Breadcrumb] Route meta not available yet');
        return;
      }

      const { params } = this.route;
      if (!this.route.meta.primary_breadcrumbs) {
        return;
      }
      let selected_breadcrumb = this.route.meta.primary_breadcrumbs;
      let previous_route_breadcrumb = '';
      if (this.$router.options.history.state.back) {
        previous_route_breadcrumb =
          this.$router.options.history.state.back.replace('/', '');
        previous_route_breadcrumb = previous_route_breadcrumb.replaceAll(
          '/',
          '_',
        );
        Object.keys(params).forEach((key) => {
          previous_route_breadcrumb = previous_route_breadcrumb.replaceAll(
            params[key],
            '',
          );
        });
        if (previous_route_breadcrumb.endsWith('_')) {
          previous_route_breadcrumb += 'breadcrumbs';
        } else {
          previous_route_breadcrumb += '_breadcrumbs';
        }
      }
      if (this.route.meta[previous_route_breadcrumb]) {
        selected_breadcrumb = this.route.meta[previous_route_breadcrumb];
      }
      const breadcrumbs = selected_breadcrumb
        .filter((breadcrumb) => {
          // Drop crumbs gated on a param that isn't present in the current route.
          // Lets one breadcrumb chain serve both "with X" and "without X" variants
          // (e.g. sub_doc_type crumb only appears when :sub_doc_type_key is set).
          if (!breadcrumb.requires_param) return true;
          return !!params[breadcrumb.requires_param];
        })
        .map((breadcrumb) => {
          const breadcrumbCopy = { ...breadcrumb };
          Object.keys(params).forEach((key) => {
            breadcrumbCopy.path = breadcrumbCopy.path.replace(
              `:${key}`,
              params[key],
            );
            breadcrumbCopy.label = breadcrumbCopy.label.replace(
              `:${key}`,
              params[key],
            );
          });
          breadcrumbCopy.path = breadcrumbCopy.path.replace(/:([^\/]*)/g, ''); // Replace every param that is not set (such as :sub_doc_type)
          return {
            label: this.$t(this.formatLabel(breadcrumbCopy.label)),
            to: breadcrumbCopy.path,
          };
        });
      this.breadcrumbs = breadcrumbs;
    },
  },
};
</script>
<style lang="scss" scoped>
.breadcrumb-label {
  font-size: 13px;
  font-weight: 500;
  text-transform: capitalize;
}

.breadcrumb-current .breadcrumb-label {
  font-weight: 600;
}
</style>
