<template>
  <div v-if="name !== ''" class="full-width sub-header bg-primary text-white" :data-test="'sub-header-' + name">
    <div v-if="!isMobile()" class="row header-padding relative">
      <span class="col-auto left-side q-ml-md">
        <q-btn
          v-if="display_back_button"
          rounded
          dense
          size="12px"
          color="primary"
          class="text-white q-mr-sm"
          @click="goBack()"
          icon="keyboard_backspace"
        ></q-btn>
        <!-- <span class="text-capitalize ellipsify" style="margin-top: 2px;"> {{ label.toLowerCase() }}</span> -->
        <Breadcrumb />
      </span>

      <span v-if="onSearch" class="col-3 search-card">
        <q-input
          class="width-150 white-field"
          dense
          autofocus
          outlined
          :placeholder="$t('search_supplier')"
          color="white"
          label-color="white"
          v-model="searchInput"
          @keyup.enter="onKeyup"
        ></q-input>
      </span>
      <slot />
      <span class="q-ml-auto gt-sm display-flex" v-if="!$route.fullPath.includes('settings/document-types')" >
        <slot name="before-counters" />
        <TaskCounters :key="locale" />
        <!-- Multi-Org Switcher (M2, SD 2860679170 §4.2) — a NEW, separate
             header icon, distinct from the sub-org switcher below. Do not
             merge these: sub-org = child orgs under one parent org; this is
             switching between separate top-level orgs the user belongs to. -->
        <span class="q-pl-sm">
          <HeaderOrgSwitchButton />
        </span>
        <span class="q-pl-md">
          <template v-for="(organization, index) in organizations" :key="index">
            <div id="sub-orgs-button">
              <q-select
                v-if="hasSubOrganizations"
                borderless
                dense
                option-value="id"
                option-label="name"
                use-input
                fill-input
                hide-selected
                emit-value
                map-options
                style="width: 200px"
                class="white-input"
                popup-content-class="dropdown-fit"
                v-model="selectedSubOrg"
                :options="filteredSubOrgs"
                @filter="searchSubOrgs"
              >
                <template v-slot:prepend>
                  <q-icon
                    v-if="organization.id == sub_org_id"
                    color="white"
                    name="mediation"
                  />
                  <q-icon
                    v-else
                    color="white"
                    name="business"
                  />
                </template>
                <template v-slot:option="scope">
                  <q-item
                    v-bind="scope.itemProps"
                    @click="setSubOrg(scope.opt)"
                    class="dark-theme-icon"
                  >
                    <q-item-section side>
                      <q-icon
                        size="xs"
                        class="icon-grey-svg"
                        :name="
                          scope.opt.id == organization.id
                            ? 'mediation'
                            : 'business'
                        "
                      />
                    </q-item-section>
                    <q-item-section>
                      <q-item-label>{{ scope.opt.name }}</q-item-label>
                      <q-tooltip>{{ scope.opt.name }}</q-tooltip>
                    </q-item-section>
                  </q-item>
                </template>
              </q-select>
              <div class="sub-org" v-else>
                <q-item class="gt-sm" dense clickable>
                  <q-item-section side>
                    <q-icon
                      color="white"
                      name="business"
                    />
                  </q-item-section>
                  <q-item-section>
                    <span class="text-capitalize">
                      {{ sub_org_name ? sub_org_name : organization.name }}
                    </span>
                  </q-item-section>
                </q-item>
              </div>
            </div>
          </template>
          </span>
          <RegionFlag />
          <span>
            <NotificationHistory />
          </span>
          <span class="" v-if="isTourKeyValid()">
            <q-btn id='walkthrough_button' flat class="helpbtn" color="white" icon="info" @click="triggerWalkthroughAction(true)" target="_blank">
              <q-tooltip>{{ $t('replay_walkthrough') }}</q-tooltip>
            </q-btn>
          </span>
          <span class="" v-if="display_help_link">
            <q-btn id='help_button' flat class="helpbtn" color="white" icon="help" @click="goHelp()" target="_blank" />
          </span>
        </span>
    </div>

    <div v-else class="row header-padding">
      <span class="col-6 left-side q-mr-auto ml-24">
        <q-btn
          class="mb-2"
          flat
          @click="drawer = !drawer"
          round
          dense
          icon="menu"
        />
        <span class="text-capitalize q-ml-sm">{{ label.toLowerCase() }}</span>
      </span>
    </div>
  </div>

  <template v-if="show_expiry_alert">
    <SubscriptionAlert />
  </template>

  <WalkthroughGuide
    :steps="tourSteps"
    :key="locale"
    v-if="triggerWalkthrough"
    :forceShow="isManualTrigger"
  />
</template>

<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { storeToRefs } from 'pinia';
import cache from 'src/utils/cache';
import stringUtil from 'src/utils/string';
import { logger } from 'src/utils/logger';
import { defineComponent, ref, computed } from 'vue';
import { useTolgee } from '@tolgee/vue';
import { isMobile } from 'src/supplier/utils';
import { getLink, getSettingsHelpKey } from 'src/utils/helpLinks';
import type { dynamicObj } from 'src/pages/assets';
import helperMixin from 'src/mixins/helperMixin.js';
import { ApiExceptions } from 'src/exceptions/index';
import Breadcrumb from 'src/components/BreadCrumb.vue';
import { UserSubOrg } from 'src/utils/organization/index';
import { useSettingStore, useUserStore } from 'src/store/main';
import TaskCounters from 'src/pages/Dashboard/TaskCounters.vue';
import SubscriptionAlert from 'src/pages/UserSubscription/SubscriptionAlert.vue';
import { allSubOrgsMenu, sub_org_sort_order, all_sub_org_setting, walkthrough_completed_setting }  from 'src/constants';
import WalkthroughGuide from 'src/components/WalkthroughGuide.vue';
import NotificationHistory from 'src/components/notifications/NotificationHistory.vue';
import RegionFlag from 'src/components/RegionFlag.vue';
import HeaderOrgSwitchButton from 'src/components/LayoutHeader/HeaderOrgSwitchButton.vue';
import docTablesUtilsMixins from 'src/utils/docTablesUtil';
import stepsData from 'src/assets/walkthrough-steps.json';
import { TourKey, validTourKeys } from 'src/components/WalkthroughKeys';
export default defineComponent({
  components: {
    SubscriptionAlert,
    TaskCounters,
    Breadcrumb,
    WalkthroughGuide,
    NotificationHistory,
    RegionFlag,
    HeaderOrgSwitchButton,
  },
  mixins: [cache, helperMixin, stringUtil, docTablesUtilsMixins],
  props: {
    onSearch: {
      type: Boolean,
      default: false,
    },
    name: {
      type: String,
      default: '',
    },
    label: {
      type: String,
      default: '',
    },
    show_expiry_alert: {
      type: Boolean,
      default: true,
    },
    display_help_link: {
      type: Boolean,
      default: true,
    },
    display_back_button: {
      type: Boolean,
      default: false,
    },
    back_to_link: {
      type: String,
      default: '',
    },
  },
  data() {
    return {
      searchInput: ref(''),
      orgSearch: ref(''),
      filteredSubOrgs: ref([] as any),
      is_sub_org: false,
      fullPath: this.$route.path.split('/').filter(Boolean),
    };
  },
  mounted: function () {
    logger.debug('[SubHeader Debug] Component mounted');
    logger.debug('[SubHeader Debug] Current route path:', this.$route.fullPath);
    logger.debug(
      '[SubHeader Debug] Includes settings/document?',
      this.$route.fullPath.includes('settings/document-types'),
    );
    this.init();
    document.addEventListener('sort_updated', this.sortRows);
    document.addEventListener('addAllSubOrg', this.addAllSubOrg);
    document.addEventListener('removeAllSubOrg', this.removeAllSubOrg);
    document.addEventListener('openHelpPage', this.goHelp);
  },
  unmounted: function () {
    document.removeEventListener('sort_updated', this.sortRows);
    document.removeEventListener('addAllSubOrg', this.addAllSubOrg);
    document.removeEventListener('removeAllSubOrg', this.removeAllSubOrg);
    document.removeEventListener('openHelpPage', this.goHelp);
  },
  watch: {
    organizations: {
      handler(newVal, oldVal) {
        logger.debug('[SubHeader Debug] organizations changed!');
        logger.debug('[SubHeader Debug] New organizations:', newVal);
        if (newVal && newVal.length > 0) {
          logger.debug(
            '[SubHeader Debug] organizations[0].sub_organisations:',
            newVal[0]?.sub_organisations,
          );
          logger.debug(
            '[SubHeader Debug] Dropdown visibility:',
            newVal[0]?.sub_organisations?.length > 0
              ? '✓ VISIBLE'
              : '❌ HIDDEN',
          );
        }
      },
      deep: true,
    },
  },
  methods: {
    searchSubOrgs(val: string, update: any) {
      if (val === '') {
        update(() => {
          this.filteredSubOrgs = this.subOrganisationsList;
        });
        return;
      }

      update(() => {
        const needle = val.toLowerCase();
        this.filteredSubOrgs = this.subOrganisationsList.filter(
          (v: any) => v.name.toLowerCase().indexOf(needle) > -1,
        );
      });
    },
    async init() {
      try {
        logger.debug('[SubHeader Debug] init() starting...');

        await this.getUserOrganizations();
        logger.debug(
          '[SubHeader Debug] getUserOrganizations() completed. Organizations:',
          this.organizations,
        );

        await this.getSubOrgId();
        logger.debug(
          '[SubHeader Debug] getSubOrgId() completed. sub_org_id:',
          this.sub_org_id,
        );

        this.getSubInfo();
        logger.debug(
          '[SubHeader Debug] getSubInfo() completed. subOrganisationsList:',
          this.subOrganisationsList,
        );

        await this.startSettingsFetch();
        logger.debug('[SubHeader Debug] startSettingsFetch() completed');

        const selectedSubOrg = this.subOrganisationsList.find(
          (subOrg: any) => subOrg.id === this.sub_org_id,
        );
        if (selectedSubOrg && selectedSubOrg.id) {
          this.selectedSubOrg = selectedSubOrg.id;
        }
        this.filteredSubOrgs = this.subOrganisationsList;

        // Check if walkthrough should be shown - AFTER settings are loaded
        this.checkIsFirstLogin();
      } catch (err) {
        logger.error('[SubHeader Debug] Error in init():', err);
        logError(err);
      }
    },
    getSubInfo() {
      this.is_sub_org = false;
      logger.debug('[SubHeader Debug] getSubInfo() called');
      logger.debug('[SubHeader Debug] organizations:', this.organizations);
      logger.debug(
        '[SubHeader Debug] organizations.length:',
        this.organizations?.length,
      );

      if (!this.organizations || this.organizations.length == 0) {
        // Changed from warn to debug - this is expected during initial page load
        // Organizations are loaded asynchronously, so they may not be available immediately
        logger.debug(
          '[SubHeader Debug] No organizations found - data may still be loading',
        );
        return;
      }

      logger.debug(
        '[SubHeader Debug] organizations[0]:',
        this.organizations[0],
      );
      logger.debug(
        '[SubHeader Debug] organizations[0].sub_organisations:',
        this.organizations[0].sub_organisations,
      );
      logger.debug(
        '[SubHeader Debug] sub_organisations.length:',
        this.organizations[0].sub_organisations?.length,
      );

      if (this.organizations[0].sub_organisations.length == 0) {
        logger.debug(
          '[SubHeader Debug] No sub_organisations found - CROSS dropdown will be hidden',
        );
        return;
      }

      this.is_sub_org = true;
      logger.debug(
        '[SubHeader Debug] ✓ Sub-organizations found, adding to list',
      );

      this.subOrganisationsList.push(
        ...this.organizations[0].sub_organisations,
      );
      logger.debug(
        '[SubHeader Debug] subOrganisationsList after push:',
        this.subOrganisationsList,
      );

      this.sortRows();

      if (this.user_settings[all_sub_org_setting]) {
        this.addAllSubOrg();
      }
    },
    removeAllSubOrg() {
      this.subOrganisationsList.shift();
      if (allSubOrgsMenu.id == this.sub_org_id && this.subOrganisationsList.length > 0) {
        this.setSubOrg(this.subOrganisationsList[0]);
      }
    },
    addAllSubOrg() {
      // Safety check: ensure organizations data is available
      if (!this.organizations || this.organizations.length === 0) {
        logger.debug('[SubHeader Debug] addAllSubOrg() called but organizations not yet loaded');
        return;
      }

      this.allSubOrgsMenu.id = this.organizations[0].id;
      this.allSubOrgsMenu.org_id = this.organizations[0].id;
      this.subOrganisationsList.unshift(this.allSubOrgsMenu);
    },
    sortRows() {
      const sortOrderStr = this.user_settings[sub_org_sort_order];
      if (!sortOrderStr) {
        return;
      }
      const sortOrder = JSON.parse(sortOrderStr);
      const isDescendingOrder = sortOrder.sort_order == 'desc';

      this.subOrganisationsList = this.customSort(
        this.subOrganisationsList,
        sortOrder.sort_by,
        isDescendingOrder,
      );
      this.filteredSubOrgs = this.subOrganisationsList;
    },

    async setSubOrg(selected_sub_org: any) {
      try {
        logger.debug(
          '[SubHeader Debug] setSubOrg() called with:',
          selected_sub_org,
        );
        this.showLoading();
        const id = String(selected_sub_org.id);
        if (!id) {
          logger.error('[SubHeader Debug] ❌ No organization ID selected!');
          notify.error('no organization selected');
          return;
        }
        logger.debug('[SubHeader Debug] Setting sub org ID to:', id);
        this.selectedSubOrg = selected_sub_org.id;
        await UserSubOrg.setSubOrgId(id);
        logger.debug('[SubHeader Debug] ✓ Sub org ID saved');
        await this.refreshAndGetSubOrgId();
        logger.debug('[SubHeader Debug] ✓ Sub org refreshed');
        this.$router.go(0);
      } catch (err) {
        logger.error('[SubHeader Debug] ❌ Error in setSubOrg():', err);
        const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
        notify.error(msg);
        logError(err);
      } finally {
        this.hideLoading();
      }
      return;
    },
    onKeyup() {
      const searchItem = this.searchInput.toLowerCase();
      this.$emit('matched-settings', searchItem);
    },
    goHelp() {
      const path = this.$route.path;
      const key = path.startsWith('/settings') ? getSettingsHelpKey(path) : this.name;
      let link = getLink(key);
      if (!link) {
        return;
      }
      if (typeof link != 'string') {
        link = 'https://docs.docbits.com/';
      }
      window.open(link);
    },
    goBack() {
      // Use router.push for internal paths to avoid a full page reload
      // (which loses unsaved state and re-downloads the entire app).
      // External URLs still go through window.location.
      const link = this.back_to_link;
      if (!link) return;
      const isExternal = /^(https?:)?\/\//i.test(link);
      if (isExternal) {
        window.location.href = link;
      } else {
        this.$router.push(link).catch(() => {
          // Swallow navigation duplicated/cancelled errors — they're benign
        });
      }
    },

    async checkIsFirstLogin() {
      // Check if walkthrough has been completed from backend user settings
      let value = this.user_settings[walkthrough_completed_setting];

      // Migration: If no backend value exists, check old cookie and migrate
      if (value === undefined || value === null) {
        // Only check cookie if the method exists (from mixin)
        const self = this as any;
        if (typeof self.getDataFromCookies === 'function') {
          const cookieValue = self.getDataFromCookies('is_walkthrough_done');
          if (cookieValue === '1') {
            // Migrate cookie value to backend
            try {
              await this.updateSetting(walkthrough_completed_setting, true);
              value = true;
            } catch (error) {
              logError('Failed to migrate walkthrough cookie to backend:', error);
            }
          }
        }
      }

      // Normalize to boolean - handles string "true"/"false", numbers 1/0, etc.
      const walkthroughCompleted = value === true || value === 1 || value === '1' || value === 'true';

      // Show walkthrough only if not completed
      if (!walkthroughCompleted) {
        this.triggerWalkthroughAction();
      }
    },
    isTourKeyValid() {
      const path = String(this.fullPath[0]);

      // Returns true if path is a valid TourKey
      return validTourKeys.includes(path as TourKey);
    },
    async triggerWalkthroughAction(isManualTrigger = false) {
      try {
        // Only reset preference to false if user manually clicked the info button
        // This allows them to replay the walkthrough and see it on next login
        if (isManualTrigger) {
          await this.settings_store.setUserPreferences(walkthrough_completed_setting, false);
        }

        const path = String(this.fullPath[0]);
        let tourKey: TourKey = 'default';

        // Check if the path is in the validTourKeys array
        if (validTourKeys.includes(path as TourKey)) {
          tourKey = path as TourKey;
        }

        this.tourSteps = stepsData[tourKey].map((step) => ({
          ...step,
          text: this.$t(step.text)
        }));
        this.enableWalkthroughGuide();
      } catch (error) {
        logError('Failed to reset walkthrough preference:', error);
        // Still show walkthrough even if preference save failed
        const path = String(this.fullPath[0]);
        let tourKey: TourKey = 'default';
        if (validTourKeys.includes(path as TourKey)) {
          tourKey = path as TourKey;
        }
        this.tourSteps = stepsData[tourKey].map((step) => ({
          ...step,
          text: this.$t(step.text)
        }));
        this.enableWalkthroughGuide();
      }
    },

    enableWalkthroughGuide() {
      // Force component re-render by toggling the key
      // Don't destroy the component - let it handle its own lifecycle
      this.triggerWalkthrough = false;
      this.$nextTick(() => {
        this.triggerWalkthrough = true;
      });
    },
  },
  setup() {
    const tolgee = useTolgee(['language']);
    const locale = computed(() => tolgee.value.getLanguage() || 'en');

    const settings_store = useSettingStore();
    const { startSettingsFetch, updateSetting } = settings_store;
    const { user_settings, drawer } = storeToRefs(settings_store);

    const user_store = useUserStore();
    const {
      getUserOrganizations,
      getSubOrgId,
      refreshAndGetSubOrgId,
      refreshUserOrganizations,
    } = user_store;
    const {
      userFullName,
      organizations,
      sub_org_id,
      sub_org_name,
      main_orgainzation,
      allSubOrgsMenu,
    } = storeToRefs(user_store);

    // Computed property to reactively check if sub-organizations exist
    // This fixes race condition where template checked before API data loaded
    const hasSubOrganizations = computed(() => {
      logger.debug('[SubHeader] Computed hasSubOrganizations evaluating...');
      logger.debug('[SubHeader] organizations.value:', organizations.value);

      if (!organizations.value || !Array.isArray(organizations.value)) {
        logger.debug('[SubHeader] ❌ organizations is null or not array');
        return false;
      }

      if (organizations.value.length === 0) {
        logger.debug('[SubHeader] ❌ organizations array is empty');
        return false;
      }

      const firstOrg = organizations.value[0];
      if (!firstOrg) {
        logger.debug('[SubHeader] ❌ First organization is null/undefined');
        return false;
      }

      if (!firstOrg.sub_organisations) {
        logger.debug(
          '[SubHeader] ❌ First org missing sub_organisations field',
        );
        return false;
      }

      if (!Array.isArray(firstOrg.sub_organisations)) {
        logger.debug('[SubHeader] ❌ sub_organisations is not an array');
        return false;
      }

      const hasSubOrgs = firstOrg.sub_organisations.length > 0;
      logger.debug(
        '[SubHeader]',
        hasSubOrgs ? '✅' : '❌',
        'sub_organisations length:',
        firstOrg.sub_organisations.length,
      );

      return hasSubOrgs;
    });

    return {
      locale,
      user_settings,
      drawer,
      settings_store,
      isMobile,
      getUserOrganizations,
      startSettingsFetch,
      updateSetting,
      getSubOrgId,
      refreshAndGetSubOrgId,
      refreshUserOrganizations,
      userFullName,
      organizations,
      sub_org_id,
      sub_org_name,
      main_orgainzation,
      allSubOrgsMenu,
      hasSubOrganizations,
      subOrganisationsList: ref([] as any),
      selectedSubOrg: ref(''),
      triggerWalkthrough: ref(false),
      tourSteps: ref([] as any),
      isManualTrigger: ref(false),
    };
  },
});
</script>

