<template>
  <div v-if="isAdmin" class="secondary-c-text float-right">
    <div class="flip-clock-counter" :class="priorityClass">
      <span class="counter-label gt-sm text-white text-uppercase title">
        {{ $t('pending_documents') }}:
      </span>

      <span class="pending-inline-value">{{ displayValue }}</span>

      <q-tooltip>{{ priorityTooltip }}</q-tooltip>
    </div>
  </div>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
import { defineComponent, ref } from 'vue';
import { WEB_SOCKET_URL } from 'src/pages/APIs';
import { useWebSocketStore, useUserStore } from 'src/store/main';
import { documentListApiService } from 'src/services';
import { isUserAdmin } from 'src/utils/UserDetails';
import { logger } from 'src/utils/logger';

const DEBOUNCE_MS = 1500;
const ANIMATION_STEP_MS = 50;
const ANIMATION_STEPS = 10;

export default defineComponent({
  watch: {
    isConnected: {
      handler: function () {
        this.subscribeToTasksCountChannel();
      },
    },
    pending_docs: {
      deep: true,
      handler: function (newVal) {
        const rawCount = Number(newVal?.total) || 0;
        this.debouncedSetTarget(rawCount);
      },
    },
  },
  async mounted() {
    // Resolve admin status from the freshly-loaded profile. getProfile() is
    // deduped via profileReqPromise, so this shares any in-flight request
    // (e.g. the one SettingsLayout fires) rather than hitting the API twice.
    // Needed because child components mount before the parent layout finishes
    // loading the profile, so user_details may not be in LocalStorage yet.
    try {
      await this.userStore.getProfile();
    } catch {
      // Fall back to whatever LocalStorage already holds.
    }
    // The await above may have spanned an unmount — unmounted() has then
    // already cleared listeners/timers, so bail before re-registering them.
    if (this.isDestroyed) {
      return;
    }
    this.isAdmin = isUserAdmin();

    // Badge is admin-only — skip stats fetch / WS subscription for normal users.
    if (!this.isAdmin) {
      return;
    }
    this.initView();
    document.addEventListener('dashboard_refresh', this.refreshCount);

    if (this.$route?.query?.fliptest !== undefined) {
      this.startFlipTest();
    }
  },
  unmounted: function () {
    this.isDestroyed = true;
    document.removeEventListener('dashboard_refresh', this.refreshCount);
    this.clearCounterInterval();
    this.stopFlipTest();
    this.clearAnimation();
    clearTimeout(this.debounceTimer);
  },
  data() {
    return {
      CounterInterval: 0 as any,
      FlipTestInterval: 0 as any,
      debounceTimer: 0 as any,
      animationTimer: 0 as any,
      targetCount: 0,
      // Reactive so the badge appears once the profile loads (see mounted()).
      // Initialised from LocalStorage for the already-authenticated case (F5).
      isAdmin: isUserAdmin(),
      // Guards the async mounted(): if the component is torn down while
      // getProfile() is still pending, we must not resume side effects.
      isDestroyed: false,
    };
  },
  methods: {
    async initView() {
      try {
        await this.getStats();
        if (WEB_SOCKET_URL) {
          this.subscribeToTasksCountChannel();
          return;
        }
        this.intervalManager();
      } catch (err) {
        this.clearCounterInterval();
      } finally {
        this.request_processing = false;
      }
    },

    /**
     * Set display value immediately (used for initial API load).
     */
    setImmediate(count: number) {
      const value = Math.min(Math.max(count, 0), 999);
      this.targetCount = value;
      this.displayValue = value;
      this.updateDocQueue(value);
    },

    /**
     * Buffer rapid WebSocket updates — only act on the latest value
     * after the debounce window expires.
     */
    debouncedSetTarget(count: number) {
      clearTimeout(this.debounceTimer);
      this.debounceTimer = setTimeout(() => {
        const value = Math.min(Math.max(count, 0), 999);
        this.targetCount = value;
        this.updateDocQueue(value);
        this.startAnimation();
      }, DEBOUNCE_MS);
    },

    /**
     * Animate displayValue towards targetCount in ~10 steps over ~500ms.
     * Step size is fixed at start so the animation completes in constant time
     * regardless of distance (avoids Zeno's paradox with diminishing steps).
     */
    startAnimation() {
      this.clearAnimation();

      if (this.displayValue === this.targetCount) return;

      const totalDiff = Math.abs(this.targetCount - this.displayValue);
      const fixedStep = Math.max(1, Math.ceil(totalDiff / ANIMATION_STEPS));

      this.animationTimer = setInterval(() => {
        const diff = this.targetCount - this.displayValue;
        if (diff === 0) {
          this.clearAnimation();
          return;
        }

        if (Math.abs(diff) <= fixedStep) {
          this.displayValue = this.targetCount;
        } else {
          this.displayValue += diff > 0 ? fixedStep : -fixedStep;
        }
      }, ANIMATION_STEP_MS);
    },

    clearAnimation() {
      if (this.animationTimer) {
        clearInterval(this.animationTimer);
        this.animationTimer = 0;
      }
    },

    updateDocQueue(value: number) {
      this.doc_queue = value < 10 ? `0${value}` : value;
    },

    refreshCount() {
      if (this.request_processing) {
        return;
      }
      this.getStats();
    },

    async getStats() {
      if (this.subscribed_channels.has('pending_docs')) {
        return;
      }

      this.request_processing = true;
      // DB-truth count via the new /get_pending_documents_count
      // endpoint — replaces the old getPendingTasksCount which read
      // Celery queue depth and dropped to 0 the moment workers
      // pulled tasks. Same response shape ({total, load}), so
      // downstream display logic is unchanged.
      const response = await documentListApiService.getPendingDocumentsCount();
      try {
        if (!response) {
          this.clearCounterInterval();
          throw response;
        }
        const total = Number(response.total);
        if (!isNaN(total)) {
          this.setImmediate(total);
        }
      } catch (err) {
        logger.error('[TaskCounters]', 'Failed to get pending tasks count:', err);
      } finally {
        this.request_processing = false;
      }
    },

    clearCounterInterval() {
      clearInterval(this.CounterInterval);
    },

    intervalManager() {
      this.CounterInterval = setInterval(() => {
        this.getStats();
      }, 60000);
    },

    subscribeToTasksCountChannel() {
      // Single subscribe chokepoint — called from initView() and the
      // isConnected watcher. Guard here so no path subscribes a non-admin.
      if (!this.isAdmin) {
        return;
      }
      if (this.$route.path !== '/dashboard') {
        return;
      }

      this.subscribeToChannel('pending_docs');
    },

    startFlipTest() {
      logger.info('[TaskCounters]', 'Flip test mode enabled - random values 1-300 every 2s');
      const randomValue = Math.floor(Math.random() * 300) + 1;
      this.setImmediate(randomValue);

      this.FlipTestInterval = setInterval(() => {
        const newValue = Math.floor(Math.random() * 300) + 1;
        logger.debug('[TaskCounters]', `Flip test: ${newValue}`);
        this.targetCount = Math.min(newValue, 999);
        this.updateDocQueue(this.targetCount);
        this.startAnimation();
      }, 2000);
    },

    stopFlipTest() {
      if (this.FlipTestInterval) {
        clearInterval(this.FlipTestInterval);
        this.FlipTestInterval = 0;
        logger.info('[TaskCounters]', 'Flip test mode stopped');
      }
    },
  },
  computed: {
    formattedCount(): number {
      return this.displayValue;
    },
    priorityClass(): string {
      const count = this.displayValue;
      if (count === 0) return 'priority-none';
      if (count <= 20) return 'priority-low';
      if (count <= 50) return 'priority-medium';
      return 'priority-high';
    },
    priorityTooltip(): string {
      const count = Number(this.doc_queue) || 0;
      if (count <= 20) return this.$t('low');
      if (count <= 50) return this.$t('medium');
      return this.$t('high');
    },
  },
  setup() {
    const websocket_store = useWebSocketStore();
    const { isConnected, pending_docs, subscribed_channels } =
      storeToRefs(websocket_store);
    const { subscribeToChannel } = websocket_store;
    return {
      userStore: useUserStore(),
      subscribed_channels,
      pending_docs,
      subscribeToChannel,
      isConnected,
      doc_queue: ref('00' as string | number),
      request_processing: ref(false),
      displayValue: ref(0),
    };
  },
});
</script>

<style lang="scss" scoped>
.flip-clock-counter {
  display: flex;
  align-items: center;
  gap: 10px;
}

.counter-label {
  margin: 0 5px;
}

// Inline value — hidden by default, shown by shadcn-theme.scss
.pending-inline-value {
  display: none;
}
</style>
